/* SYSTEM-AWARE APPLE-STYLE THEME SWITCH ----------------------------------- */
#theme-toggle.theme-switch{
  position:relative;width:58px;height:32px;min-width:58px;padding:0!important;border:0!important;
  border-radius:999px!important;background:transparent!important;box-shadow:none!important;
  display:block;overflow:visible;isolation:isolate;touch-action:manipulation;
}
#theme-toggle .theme-switch__track{
  position:absolute;inset:0;border-radius:999px;background:#d8e1e5;
  border:1px solid rgba(8,35,49,.16);box-shadow:inset 0 0 0 1px rgba(255,255,255,.22);
  transition:background-color .28s cubic-bezier(.25,.1,.25,1),border-color .28s ease;
}
#theme-toggle .theme-switch__thumb{
  position:absolute;top:3px;left:3px;width:26px;height:26px;border-radius:50%;background:#fff;
  display:grid;place-items:center;box-shadow:0 2px 6px rgba(0,20,32,.25),0 1px 2px rgba(0,20,32,.18);
  transform:translate3d(0,0,0);transition:transform .30s cubic-bezier(.34,1.15,.64,1),background-color .28s ease;
  will-change:transform;backface-visibility:hidden;
}
#theme-toggle .theme-switch__sun,#theme-toggle .theme-switch__moon{
  position:absolute;width:16px;height:16px;transition:opacity .18s ease,transform .28s cubic-bezier(.34,1.15,.64,1);
}
#theme-toggle .theme-switch__sun{fill:#f5a623;stroke:#f5a623;stroke-width:1.7;stroke-linecap:round;opacity:1;transform:scale(1) rotate(0deg)}
#theme-toggle .theme-switch__sun circle{stroke:none}
#theme-toggle .theme-switch__sun g{fill:none}
#theme-toggle .theme-switch__moon{fill:#c9dcff;opacity:0;transform:scale(.65) rotate(-18deg)}
body.night #theme-toggle .theme-switch__track{background:#315b83;border-color:rgba(172,208,242,.24)}
body.night #theme-toggle .theme-switch__thumb{transform:translate3d(26px,0,0);background:#162c42}
body.night #theme-toggle .theme-switch__sun{opacity:0;transform:scale(.65) rotate(18deg)}
body.night #theme-toggle .theme-switch__moon{opacity:1;transform:scale(1) rotate(0deg)}
#theme-toggle:hover .theme-switch__thumb{box-shadow:0 3px 8px rgba(0,20,32,.30),0 1px 2px rgba(0,20,32,.18)}
#theme-toggle:active .theme-switch__thumb{width:29px}
body.night #theme-toggle:active .theme-switch__thumb{transform:translate3d(23px,0,0)}
#theme-toggle:focus-visible{outline:3px solid #addff9;outline-offset:5px}
@media(max-width:600px){#theme-toggle.theme-switch{width:56px;height:32px;min-width:56px}}
@media(prefers-reduced-motion:reduce){#theme-toggle .theme-switch__track,#theme-toggle .theme-switch__thumb,#theme-toggle .theme-switch__sun,#theme-toggle .theme-switch__moon{transition:none!important}}

/* CLEAN JELLYFISH LOADER --------------------------------------------------- */
#ocean-loader{
  position:fixed;inset:0;z-index:9999;display:grid;place-items:center;
  background:radial-gradient(circle at 50% 44%,#0b3146 0,#071f30 34%,#061622 70%);
  opacity:1;visibility:visible;pointer-events:auto;
  transition:opacity .42s ease,visibility 0s linear .42s;
}
body[data-ready] #ocean-loader{opacity:0;visibility:hidden;pointer-events:none}
body:not([data-ready]){overflow:hidden}
body:not([data-ready]) .nav,body:not([data-ready]) main,body:not([data-ready]) .hud,body:not([data-ready]) #dive-progress{opacity:0;visibility:hidden}
body[data-ready] .nav,body[data-ready] main,body[data-ready] .hud,body[data-ready] #dive-progress{visibility:visible}
.ocean-loader__content{display:flex;flex-direction:column;align-items:center;gap:18px;text-align:center;padding:24px}
.ocean-loader__stage{position:relative;width:108px;height:144px;display:grid;place-items:center;contain:layout paint style}
