.ocean-loader__jelly{display:block;width:98px;height:126px;overflow:visible}
.ocean-loader__label{font:600 11px/1.4 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;letter-spacing:.15em;text-transform:uppercase;color:#cbeaf4}
.ocean-loader__hint{--tip-height:44px;font-size:12px;line-height:1.35;color:#7faec0;width:min(380px,86vw);height:var(--tip-height);overflow:hidden;position:relative;text-align:center;contain:paint;isolation:isolate}.ocean-loader__tip-strip{display:flex;flex-direction:column;width:100%;will-change:transform;transform:translate3d(0,0,0);backface-visibility:hidden;animation:ocean-tip-reel 25s steps(50,end) infinite}.ocean-loader__tip{flex:0 0 var(--tip-height);height:var(--tip-height);display:flex;align-items:center;justify-content:center;padding:0 5px;box-sizing:border-box;color:inherit;text-align:center}@keyframes ocean-tip-reel{to{transform:translate3d(0,calc(var(--tip-height) * -50),0)}}.ocean-loader__tip-strip,.ocean-loader__tip{pointer-events:none}@media(max-width:600px){.ocean-loader__hint{--tip-height:48px;width:min(330px,88vw)}}
@keyframes jelly-float{
  0%,100%{transform:translate3d(0,4px,0) rotate(-1.2deg)}
  28%{transform:translate3d(2px,-2px,0) rotate(.5deg)}
  55%{transform:translate3d(0,-7px,0) rotate(1deg)}
