<style id="ocean-marketing-palette">
/* NEUTRAL OCEAN CLIENT PALETTE ---------------------------------------------
   The reef carries the personality. The interface stays quiet, opaque,
   professional, and broadly suitable for corporate, education, nonprofit,
   government, accessibility, agency, and small-business clients. */
:root{
  --ui-bg:#07171D;
  --ui-surface:#0D222A;
  --ui-surface-soft:#122B34;
  --ui-text:#EDF4F5;
  --ui-muted:#A7B8BD;
  --ui-primary:#69B8BC;
  --ui-primary-hover:#83C9CC;
  --ui-secondary:#7BAFC1;
  --ui-on-primary:#07171D;
  --ui-border:#27434C;
  --ui-border-strong:#35545E;
  --ui-focus:#69B8BC;
  --ui-shadow:rgba(0,0,0,.24);
  --sand:var(--ui-text);
  --blue:var(--ui-secondary);
  --ink:var(--ui-text);
}

html{background:var(--ui-bg)}
body{background:var(--ui-bg);color:var(--ui-text);transition:background-color .22s ease,color .22s ease}
::selection{background:var(--ui-primary);color:var(--ui-on-primary)}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline-color:var(--ui-focus)}

/* Navigation */
.nav{color:var(--ui-text);text-shadow:0 1px 16px rgba(255,255,255,.30)}
body.night .nav{color:var(--ui-text);text-shadow:0 1px 16px rgba(0,0,0,.38)}
.nav a{transition:color .18s ease,opacity .18s ease}
.nav-links a:hover,.nav-links a:focus-visible,.brand:hover{color:var(--ui-primary)}

/* Opaque content surfaces */
.glass,.hero .glass,body.night .hero .glass{
  color:var(--ui-text);
  background:var(--ui-surface)!important;
  border:1px solid var(--ui-border)!important;
  box-shadow:0 18px 44px var(--ui-shadow)!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}
.eyebrow,.hero .eyebrow,body.night .hero .eyebrow{color:var(--ui-primary)}
.muted,.hero .muted,body.night .hero .muted,.project-description,.service p{color:var(--ui-muted)}
.domain{color:var(--ui-secondary)}
.role{border-color:var(--ui-border-strong);color:var(--ui-primary);background:var(--ui-surface-soft)}
.service,.footer{border-color:var(--ui-border)}

/* Restrained actions */
.button,.hero .button,body.night .hero .button{
  color:var(--ui-text);
  background:var(--ui-surface);
  border-color:var(--ui-border-strong);
  box-shadow:none;
}
.button:hover,.hero .button:hover,body.night .hero .button:hover{
  color:var(--ui-primary-hover);
  background:var(--ui-surface-soft);
  border-color:var(--ui-primary);
}
.button.primary,.hero .button.primary,body.night .hero .button.primary{
  background:var(--ui-primary);
  color:var(--ui-on-primary);
  border-color:var(--ui-primary);
  box-shadow:none;
}
.button.primary:hover,.hero .button.primary:hover,body.night .hero .button.primary:hover{
  background:var(--ui-primary-hover);
  border-color:var(--ui-primary-hover);
  color:var(--ui-on-primary);
}
.email{color:var(--ui-primary);font-weight:600}
.email:hover{color:var(--ui-primary-hover)}
.copy{color:var(--ui-secondary)}
.copy:hover{color:var(--ui-primary)}

/* Forms */
label{color:var(--ui-muted)}
input,textarea{
  color:var(--ui-text);
  background:var(--ui-surface-soft);
  border-color:var(--ui-border-strong);
  caret-color:var(--ui-primary);
}
input::placeholder,textarea::placeholder{color:var(--ui-muted);opacity:.82}
input:focus,textarea:focus{border-color:var(--ui-primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--ui-primary) 14%,transparent);outline:0}
.form-note,#form-message{color:var(--ui-muted)}

/* Project imagery remains project-specific. */
.project-cover{background:var(--ui-surface-soft)}

/* Project logos: clean, centered, and never cropped. These intentionally override
   the legacy Gallaudet artwork/cover rules from the original portfolio. */
.project-cover.logo-cover{
  display:flex;
  align-items:center;
  justify-content:center;
  height:220px;
  overflow:hidden;
  background:var(--ui-surface);
  border:1px solid var(--ui-border);
}
.project-cover.logo-cover::before,
.project-cover.logo-cover::after{content:none!important;display:none!important}
.project-cover.logo-cover img{
  display:block;
  width:auto!important;
  height:auto!important;
  max-width:84%!important;
  max-height:72%!important;
  object-fit:contain!important;
  object-position:center center!important;
  margin:auto;
  background:transparent!important;
}
.project-cover.logo-cover--gallaudet img{max-width:78%!important;max-height:68%!important}
.project-cover.logo-cover--cad img{max-width:82%!important;max-height:70%!important}
.project-cover.logo-cover--dwave img{max-width:82%!important;max-height:68%!important}
@media(max-width:700px){
  .project-cover.logo-cover{height:190px;}
  .project-cover.logo-cover img{max-width:86%!important;max-height:70%!important}
  .project-cover.logo-cover--gallaudet img{max-width:80%!important;max-height:66%!important}
}

/* HUD */
.icon-control,#pause{
  color:var(--ui-text);
  background:var(--ui-surface)!important;
  border-color:var(--ui-border-strong);
  box-shadow:0 6px 18px var(--ui-shadow)!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}
.icon-control:hover,#pause:hover{background:var(--ui-surface-soft)!important;border-color:var(--ui-primary)}
#pause .pause-icon .bar{fill:var(--ui-secondary)}
#pause .play-icon .triangle{fill:var(--ui-primary)}

/* System-aware Apple-style switch, kept neutral. */
#theme-toggle .theme-switch__track{
  background:var(--ui-surface-soft);
  border-color:var(--ui-border-strong);
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.18);
}
#theme-toggle .theme-switch__thumb{background:var(--ui-surface);box-shadow:0 2px 6px var(--ui-shadow)}
#theme-toggle .theme-switch__sun{fill:#60737B;stroke:#60737B}
#theme-toggle .theme-switch__moon{fill:#8FA8B1}
body.night #theme-toggle .theme-switch__track{background:#1A343E;border-color:var(--ui-border-strong)}
body.night #theme-toggle .theme-switch__thumb{background:var(--ui-surface)}
#theme-toggle:focus-visible{outline-color:var(--ui-focus)}

/* Scroll progress / diver --------------------------------------------------
   Identical in light and dark modes: preserve the dark-mode treatment as the
   single visual system for the scuba progress control. */
#dive-progress{color:#AFC8CF}
.dive-track{background:#35545E}
.dive-fill{background:#9CB7BE}
.diver-position{color:#AFC8CF;transition:color .25s ease,opacity .35s ease,filter .35s ease}
.diver-position:focus-visible{outline-color:#D9F4FB}
.scuba-diver{filter:drop-shadow(0 1px 3px rgba(0,22,34,.32));transition:filter .35s ease}
body.at-bottom .diver-position{color:#91A8AE;opacity:.72}
body.at-bottom .scuba-diver{filter:drop-shadow(0 1px 2px rgba(0,0,0,.18)) brightness(.88)}
body.diver-dragging .diver-position,.diver-position.is-dragging{color:#E9FBFF;opacity:1}
body.diver-dragging .scuba-diver,.diver-position.is-dragging .scuba-diver{filter:drop-shadow(0 1px 4px rgba(0,22,34,.38)) brightness(1.06)}

/* Loader stays oceanic, but subdued. */
#ocean-loader{background:#07171D;color:#EDF4F5}
.ocean-loader__label{color:#A7B8BD}
.ocean-loader__hint{color:#7BAFC1}
.ocean-loader__halo{background:radial-gradient(circle,rgba(105,184,188,.16) 0,rgba(105,184,188,.05) 46%,transparent 72%)}

/* Misc */
#status{background:var(--ui-surface);color:var(--ui-text);border:1px solid var(--ui-border)}
.skip:focus{background:var(--ui-surface);color:var(--ui-text);border:1px solid var(--ui-primary)}
.scroll-note{color:var(--ui-muted);display:inline-flex;flex-direction:row;align-items:center;gap:7px}
.scroll-note__label{display:block;white-space:nowrap}
.scroll-arrow{display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;margin-top:-10px;color:currentColor;opacity:.82;animation:scroll-arrow-drift 1.65s cubic-bezier(.45,0,.55,1) infinite;flex:0 0 auto}
.scroll-arrow svg{display:block;width:16px;height:16px;overflow:visible}
@keyframes scroll-arrow-drift{0%,100%{transform:translate3d(0,-1px,0);opacity:.52}50%{transform:translate3d(0,5px,0);opacity:1}}

@media(max-width:700px){
  .glass,.hero .glass,body.night .hero .glass{background:var(--ui-surface)!important}
}
@media(prefers-reduced-motion:reduce){body{transition:none}.scroll-arrow{animation:none!important;transform:none;opacity:.82}}

/* Final abyss contact reveal */
.angler-contact{
  position:fixed;
  left:50%;
  bottom:clamp(78px,10vh,118px);
  z-index:4;
  width:min(92vw,760px);
  text-align:center;
  color:#F7FBFC;
  opacity:0;
  visibility:hidden;
  transform:translate3d(-50%,14px,0);
  pointer-events:none;
  transition:opacity .65s cubic-bezier(.22,1,.36,1),transform .65s cubic-bezier(.22,1,.36,1),visibility .65s;
  text-shadow:0 2px 18px rgba(0,0,0,.48);
}
body.show-angler-contact .angler-contact{
  opacity:1;
  visibility:visible;
  transform:translate3d(-50%,0,0);
  pointer-events:auto;
}
.angler-contact__label{
  margin:0 0 8px;
  font:600 10px/1.4 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  letter-spacing:.18em;
  text-transform:uppercase;
  color:rgba(247,251,252,.68);
}
.angler-contact__email{
  display:inline-block;
  color:#F7FBFC;
  font-size:clamp(20px,2.7vw,34px);
  font-weight:600;
  line-height:1.15;
  letter-spacing:-.025em;
  text-decoration:none;
  overflow-wrap:anywhere;
  text-underline-offset:.18em;
}
.angler-contact__email:hover{text-decoration:underline}
.angler-contact__email:focus-visible{outline:2px solid #F7FBFC;outline-offset:7px;border-radius:3px}
@media(max-width:700px){
  .angler-contact{bottom:max(74px,calc(env(safe-area-inset-bottom) + 66px));width:88vw}
