  #pause.icon-control{width:32px!important;min-width:32px!important;height:32px!important}
}




/* True hero-card knockout --------------------------------------------------
   The word “deeper” is literal negative space in the opaque card surface.
   A dynamically generated SVG alpha mask is aligned to the real inline word,
   so the live Three.js ocean remains visible through the letterforms. */
.hero .glass,body.night .hero .glass{
  position:relative;
  isolation:isolate;
  background:transparent!important;
}
.hero .glass::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:0;
  border-radius:inherit;
  background:var(--ui-surface);
  pointer-events:none;
  -webkit-mask-image:var(--hero-card-cutout-mask,linear-gradient(#fff,#fff));
  mask-image:var(--hero-card-cutout-mask,linear-gradient(#fff,#fff));
  -webkit-mask-size:100% 100%;
  mask-size:100% 100%;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
}
.hero .glass>*{position:relative;z-index:1}
/* Light mode: ocean shows through the word */
.hero .deep-word{
  display:inline-block;
  color:transparent!important;
  -webkit-text-fill-color:transparent!important;
  -webkit-text-stroke:0 transparent!important;
  text-shadow:none!important;
}

/* Dark mode: readable contrasting accent */
body.night .hero .deep-word{
  color:#9BE7EA!important;
  -webkit-text-fill-color:#9BE7EA!important;
  -webkit-text-stroke:0!important;
  text-shadow:0 2px 18px rgba(0,0,0,.35)!important;
}
