<style id="sea-dive-navigation">
/* OCEAN NAVIGATION --------------------------------------------------------- */
.sea-nav{
  position:fixed!important;
  top:calc(14px + env(safe-area-inset-top))!important;
  left:6vw!important;
  right:6vw!important;
  width:auto;
  min-height:62px;
  padding:8px 10px 8px 18px!important;
  display:grid!important;
  grid-template-columns:auto minmax(0,1fr) auto;
  align-items:center!important;
  gap:16px;
  transform:none;
  color:var(--ui-text)!important;
  background:var(--ui-surface);
  border:1px solid var(--ui-border);
  border-radius:15px;
  box-shadow:0 10px 34px var(--ui-shadow);
  text-shadow:none!important;
  z-index:50;
}
.sea-nav__brand{
  display:inline-flex;
  align-items:center;
  min-width:0;
  color:var(--ui-text);
  font-size:14px;
  font-weight:700;
  line-height:1.1;
  letter-spacing:-.025em;
  white-space:nowrap;
}
.sea-nav__brand:hover{color:var(--ui-primary)}
.sea-nav__desktop{
  margin-left:auto;
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:3px;
}
.sea-nav__desktop a{
  position:relative;
  min-width:74px;
  padding:9px 14px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:999px;
  color:var(--ui-text);
  transition:background-color .18s ease,color .18s ease;
}
.sea-nav__link-title{font-size:13px;font-weight:650;line-height:1.15}
.sea-nav__desktop a:hover,
.sea-nav__desktop a:focus-visible,
.sea-nav__desktop a[aria-current="location"]{
  background:var(--ui-surface-soft);
  color:var(--ui-primary);
}
.sea-nav__controls{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:7px;
  flex:0 0 auto;
}
.sea-nav__controls #theme-toggle,
.sea-nav__controls #pause{
  flex:0 0 auto;
}

@media(max-width:700px){
  html{scroll-padding-top:94px!important}
  .sea-nav{
    top:calc(10px + env(safe-area-inset-top))!important;
    left:max(18px,5vw)!important;
    right:max(18px,5vw)!important;
    min-height:58px;
    padding:7px 8px!important;
    align-items:center!important;
    justify-content:space-between;
    gap:5px!important;
    border-radius:19px;
  }
  .sea-nav__brand{display:none}
  .sea-nav__desktop{
    display:flex!important;
    flex:1 1 auto;
    min-width:0;
    margin:0;
    justify-content:flex-start;
    gap:1px;
  }
  .sea-nav__desktop a{
    min-width:0;
    padding:9px 9px;
    flex:0 1 auto;
  }
  .sea-nav__link-title{font-size:12px}
  .sea-nav__controls{gap:5px;margin-left:auto}
  .sea-nav__controls #theme-toggle.theme-switch{
    width:57px!important;
    min-width:57px!important;
    height:32px!important;
  }
  .sea-nav__controls #pause.icon-control{
    width:32px!important;
    min-width:32px!important;
    height:32px!important;
  }
  body:not([data-ready]) .sea-nav__controls{visibility:hidden}
  .hero{padding-top:clamp(108px,15svh,130px)!important}
}

@media(max-width:390px){
  .sea-nav{left:10px!important;right:10px!important}
  .sea-nav__desktop a{padding-left:7px;padding-right:7px}
  .sea-nav__link-title{font-size:11.5px}
  .sea-nav__controls{gap:4px}
}

@media(max-width:350px){
  .sea-nav__desktop a{padding-left:5px;padding-right:5px}
  .sea-nav__link-title{font-size:11px}
  .sea-nav__controls #theme-toggle.theme-switch{width:48px!important;min-width:48px!important}
}

@media(prefers-reduced-motion:reduce){.sea-nav *{transition:none!important}}
</style>
