document.addEventListener('keydown',e=>{if(e.key==='Escape'){const panel=document.querySelector('#ocean-settings');if(panel.open){panel.open=false;panel.querySelector('summary').focus()}}});
const systemDarkMode=window.matchMedia('(prefers-color-scheme: dark)');
let themePreference=null;
try{const savedTheme=localStorage.getItem('portfolio-theme');if(savedTheme==='dark'||savedTheme==='light')themePreference=savedTheme}catch{}
let nightMode=themePreference?themePreference==='dark':systemDarkMode.matches;
function applyTheme(){
  document.body.classList.toggle('night',nightMode);
  document.documentElement.style.colorScheme=nightMode?'dark':'light';
  document.documentElement.dataset.theme=nightMode?'dark':'light';
  const b=document.querySelector('#theme-toggle'),nextMode=nightMode?'light':'dark';
  b.setAttribute('aria-checked',String(nightMode));
  b.setAttribute('aria-label','Dark mode');
  b.title='Switch to '+nextMode+' mode';
  const hiddenLabel=b.querySelector('.sr-only');if(hiddenLabel)hiddenLabel.textContent='Dark mode '+(nightMode?'on':'off');
  const themeColor=document.querySelector('meta[name="theme-color"]');if(themeColor)themeColor.content=nightMode?'#07171D':'#F7F9FA';
  document.querySelectorAll('img[data-theme-light][data-theme-dark]').forEach(img=>{const next=nightMode?img.dataset.themeDark:img.dataset.themeLight;if(img.getAttribute('src')!==next)img.setAttribute('src',next)});
  window.dispatchEvent(new CustomEvent('ocean-theme',{detail:nightMode}));
}
document.querySelector('#theme-toggle').addEventListener('click',()=>{
  nightMode=!nightMode;
  themePreference=nightMode?'dark':'light';
  try{localStorage.setItem('portfolio-theme',themePreference)}catch{}
  applyTheme();
});
const followSystemTheme=event=>{if(themePreference!==null)return;nightMode=event.matches;applyTheme()};
if(systemDarkMode.addEventListener)systemDarkMode.addEventListener('change',followSystemTheme);else systemDarkMode.addListener(followSystemTheme);
applyTheme();
const progressBar=document.querySelector('#dive-progress'),diveTrack=progressBar.querySelector('.dive-track'),diverThumb=progressBar.querySelector('.diver-position');let previousScroll=scrollY,swimTimer=0,progressQueued=false,diverPointerId=null,diverGrabOffset=0,previousInlineScrollBehavior='';
function currentScrollProgress(){const max=document.documentElement.scrollHeight-innerHeight;return max>0?Math.min(1,Math.max(0,scrollY/max)):0}
function drawProgress(){progressQueued=false;const p=currentScrollProgress(),value=String(Math.round(p*100));progressBar.style.setProperty('--scroll-progress',p);diverThumb.setAttribute('aria-valuenow',value);diverThumb.setAttribute('aria-valuetext',value+'%')}
function setPageScrollProgress(p){const max=Math.max(0,document.documentElement.scrollHeight-innerHeight),clamped=Math.min(1,Math.max(0,p));window.scrollTo(0,clamped*max);drawProgress()}
function dragDiverTo(clientX){const rect=diveTrack.getBoundingClientRect();if(rect.width<=0)return;const x=Math.min(rect.right,Math.max(rect.left,clientX-diverGrabOffset));setPageScrollProgress((x-rect.left)/rect.width)}
function endDiverDrag(e){if(diverPointerId===null||(e&&e.pointerId!==undefined&&e.pointerId!==diverPointerId))return;const releasedPointerId=diverPointerId;diverPointerId=null;diverGrabOffset=0;diverThumb.classList.remove('is-dragging');document.body.classList.remove('diver-dragging');document.documentElement.style.scrollBehavior=previousInlineScrollBehavior;try{if(diverThumb.hasPointerCapture?.(releasedPointerId))diverThumb.releasePointerCapture(releasedPointerId)}catch{}}
diverThumb.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();const rect=diveTrack.getBoundingClientRect(),p=currentScrollProgress();diverPointerId=e.pointerId;diverGrabOffset=e.clientX-(rect.left+p*rect.width);previousInlineScrollBehavior=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';diverThumb.classList.add('is-dragging');document.body.classList.add('diver-dragging');try{diverThumb.setPointerCapture(e.pointerId)}catch{}});
diverThumb.addEventListener('pointermove',e=>{if(e.pointerId!==diverPointerId)return;e.preventDefault();dragDiverTo(e.clientX)});
diverThumb.addEventListener('pointerup',endDiverDrag);diverThumb.addEventListener('pointercancel',endDiverDrag);diverThumb.addEventListener('lostpointercapture',()=>endDiverDrag());
diverThumb.addEventListener('keydown',e=>{let p=currentScrollProgress(),handled=true;switch(e.key){case'ArrowLeft':case'ArrowUp':p-=.02;break;case'ArrowRight':case'ArrowDown':p+=.02;break;case'PageUp':p-=.1;break;case'PageDown':p+=.1;break;case'Home':p=0;break;case'End':p=1;break;default:handled=false}if(!handled)return;e.preventDefault();const old=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';setPageScrollProgress(p);document.documentElement.style.scrollBehavior=old});
window.addEventListener('scroll',()=>{const down=scrollY>previousScroll+.5;previousScroll=scrollY;document.body.classList.toggle('scrolling-down',down);clearTimeout(swimTimer);if(down)swimTimer=setTimeout(()=>document.body.classList.remove('scrolling-down'),140);if(!progressQueued){progressQueued=true;requestAnimationFrame(drawProgress)}updateMobileHud()},{passive:true});function updateMobileHud(){const threshold=Math.min(innerHeight*.35,260);document.body.classList.toggle('mobile-hud-visible',innerWidth>700||scrollY>threshold)}
window.addEventListener('resize',()=>{drawProgress();updateMobileHud()});updateMobileHud();drawProgress();
// Contact drafts remain on the visitor's device until sent in their email app.
const contactEmail='avdigiovanniv@gmail.com';
function contactDraft(name,email,message){return 'mailto:'+contactEmail+'?subject='+encodeURIComponent('Portfolio inquiry from '+name)+'&body='+encodeURIComponent('Hi Anthony,\n\n'+message+'\n\n'+name+'\n'+email)}
document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const f=event.currentTarget;if(!f.reportValidity())return;const name=f.elements.name.value.trim(),email=f.elements.email.value.trim(),message=f.elements.message.value.trim();if(!name||message.length<10){document.querySelector('#form-message').textContent='Please include your name and a short message.';return}window.location.href=contactDraft(name,email,message);document.querySelector('#form-message').textContent='If your email app didn’t open, use the direct email link. Your message has not been sent yet.'});
document.querySelector('#copy-email').addEventListener('click',async event=>{const button=event.currentTarget;try{await navigator.clipboard.writeText(contactEmail);button.textContent='Email address copied'}catch{button.textContent='avdigiovanniv@gmail.com'}});
// Optional agent support stages an inquiry; only the visitor sends email.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'prepare_contact_inquiry',title:'Prepare a portfolio inquiry',description:'Fill Anthony’s contact form for review. Does not open an email app or send a message.',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:100},email:{type:'string',format:'email',maxLength:160},message:{type:'string',minLength:10,maxLength:3000}},required:['name','email','message'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){
  if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['name','email','message'].includes(k))||typeof input.name!=='string'||!input.name.trim()||input.name.length>100||typeof input.email!=='string'||input.email.length>160||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.email)||typeof input.message!=='string'||input.message.trim().length<10||input.message.length>3000)throw new Error('Provide a name, valid email, and message of 10–3000 characters.');
  const form=document.querySelector('#contact-form');form.elements.name.value=input.name.trim();form.elements.email.value=input.email;form.elements.message.value=input.message.trim();document.querySelector('#form-message').textContent='Your inquiry is ready to review. Open the email draft when you’re ready.';document.querySelector('#contact').scrollIntoView({behavior:'smooth'});return {status:'prepared',recipient:contactEmail,sent:false};
 }};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
</script><script>
/* Keep the hero-card knockout aligned with the actual rendered word. */
(()=>{
  const card=document.querySelector('.hero .glass');
  const word=card?.querySelector('.deep-word');
  if(!card||!word)return;

  let queued=false;
  const esc=value=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

  function updateHeroCutout(){
    queued=false;
    const cardRect=card.getBoundingClientRect();
    const wordRect=word.getBoundingClientRect();
    if(cardRect.width<1||cardRect.height<1||wordRect.width<1||wordRect.height<1)return;

    const cs=getComputedStyle(word);
    const width=Math.max(1,Math.round(cardRect.width*10)/10);
    const height=Math.max(1,Math.round(cardRect.height*10)/10);
    const x=Math.round((wordRect.left-cardRect.left)*10)/10;
    const y=Math.round((wordRect.top-cardRect.top+wordRect.height/2)*10)/10;
    const fontSize=parseFloat(cs.fontSize)||72;
    const fontWeight=cs.fontWeight||'700';
    const family=(cs.fontFamily||'Arial, Helvetica, sans-serif').replace(/["']/g,'');
    const wordWidth=Math.max(1,Math.round(wordRect.width*10)/10);

    const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><defs><mask id="m" maskUnits="userSpaceOnUse" x="0" y="0" width="${width}" height="${height}"><rect width="${width}" height="${height}" fill="white"/><text x="${x}" y="${y}" dominant-baseline="central" font-family="${esc(family)}" font-size="${fontSize}" font-weight="${esc(fontWeight)}" textLength="${wordWidth}" lengthAdjust="spacingAndGlyphs" fill="black">deeper</text></mask></defs><rect width="${width}" height="${height}" fill="white" mask="url(#m)"/></svg>`;
    const url=`url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
    card.style.setProperty('--hero-card-cutout-mask',url);
  }

  function queueHeroCutout(){
    if(queued)return;
    queued=true;
    requestAnimationFrame(updateHeroCutout);
  }

  queueHeroCutout();
  window.addEventListener('resize',queueHeroCutout,{passive:true});
  window.addEventListener('orientationchange',queueHeroCutout,{passive:true});
  new ResizeObserver(queueHeroCutout).observe(card);
  if(document.fonts?.ready)document.fonts.ready.then(queueHeroCutout);
