<script id="sea-dive-navigation-script">
(()=>{
  const stops=[
    {key:'top',element:document.querySelector('#top')},
    {key:'work',element:document.querySelector('#work')},
    {key:'approach',element:document.querySelector('#approach')},
    {key:'contact',element:document.querySelector('#contact')}
  ].filter(stop=>stop.element);
  const navLinks=document.querySelectorAll('[data-nav-section]');
  let activeQueued=false;

  function updateActiveSection(){
    activeQueued=false;
    const checkpoint=scrollY+innerHeight*.38;
    let active=stops[0]?.key||'top';
    for(const stop of stops)if(stop.element.offsetTop<=checkpoint)active=stop.key;
    navLinks.forEach(link=>{
      if(link.dataset.navSection===active)link.setAttribute('aria-current','location');
      else link.removeAttribute('aria-current');
    });
  }

  function queueActiveSection(){
    if(activeQueued)return;
    activeQueued=true;
    requestAnimationFrame(updateActiveSection);
  }

  window.addEventListener('scroll',queueActiveSection,{passive:true});
  window.addEventListener('resize',queueActiveSection,{passive:true});
  updateActiveSection();
})();
</script>
