  function updatePause(){pauseButton.setAttribute('aria-label',paused?'Resume background animation':'Pause background animation');pauseButton.title=paused?'Resume motion':'Pause motion';pauseButton.setAttribute('aria-pressed',String(paused));const hiddenLabel=pauseButton.querySelector('.sr-only');if(hiddenLabel)hiddenLabel.textContent=paused?'Resume motion':'Pause motion';document.body.classList.toggle('paused',paused)}
  try{const saved=localStorage.getItem('ocean-paused');if(saved!==null)paused=saved==='true'}catch{}
  pauseButton.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('ocean-paused',String(paused))}catch{}updatePause();renderInvalidated=true;queueAnimation()});
  motionPreference.addEventListener('change',e=>{paused=e.matches;updatePause();renderInvalidated=true;queueAnimation()});
  updatePause();
  let resizeQueued=false,renderInvalidated=true;
  let viewportWidth=initialSceneWidth,viewportHeight=initialSceneHeight;
  function commitResize(){
    resizeQueued=false;
    const w=Math.max(1,ocean.clientWidth),h=Math.max(1,ocean.clientHeight);
    const dw=Math.abs(w-viewportWidth),dh=Math.abs(h-viewportHeight);
    if(dw<1&&dh<1)return;
    viewportWidth=w;viewportHeight=h;

    // The CSS canvas, WebGL drawing buffer, and perspective camera must be updated
    // together on every visible resize frame. If the CSS box changes first while
    // the drawing buffer/camera still use the old aspect, the browser stretches the
    // previous WebGL frame and circles/fish visibly become oval or "mushed".
    camera.aspect=w/h;
    camera.updateProjectionMatrix();
    renderer.setSize(w,h,false);
    particleMat.uniforms.uScale.value=h*.6;

    // DPR remains frozen for the session, so live resizing changes only dimensions,
    // never pixel density. Repaint immediately after the resize to avoid displaying
    // a stretched copy of the previous frame.
    renderInvalidated=true;
    updateJourney(0);if(!paused)update(elapsed,true);renderJourney();renderInvalidated=false;
    queueAnimation();
  }
  function resize(){
    // Coalesce multiple ResizeObserver notifications into one update per display
    // frame. Do not debounce with a timeout: during a window drag that leaves the
    // canvas visually resized while WebGL is still using stale dimensions.
    if(resizeQueued)return;
    resizeQueued=true;
    requestAnimationFrame(commitResize);
  }
  // Observe the actual fixed ocean element. Its size is the single source of truth
  // for both the renderer and camera, keeping their aspect ratios identical.
  const oceanObserver=new ResizeObserver(resize);oceanObserver.observe(ocean);
  window.addEventListener('ocean-theme',()=>{renderInvalidated=true;queueAnimation()});
  let contextLost=false;
  renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();contextLost=true;showError(new Error('WebGL context lost. Reload the page to restore the scene.'))});
  renderer.domElement.addEventListener('webglcontextrestored',()=>location.reload());
  let last=performance.now(),running=true,animationFrame=0;
  function animationTick(now){animationFrame=0;animate(now)}
  function queueAnimation(){if(!animationFrame&&running)animationFrame=requestAnimationFrame(animationTick)}
  document.addEventListener('visibilitychange',()=>{last=performance.now();if(!document.hidden&&stageVisible)queueAnimation()});
  const sceneObserver=new IntersectionObserver(entries=>{const visible=entries[0].isIntersecting;if(visible&&!stageVisible){last=performance.now();queueAnimation()}stageVisible=visible});sceneObserver.observe(ocean);
  function update(t,updateHeavy=true){
    animateDepth(t);time.value=t;
    if(reefLayer.visible){
      for(let i=0;i<shafts.length;i++){const shaft=shafts[i];shaft.g.rotation.z=-.34+Math.sin(t*.19+shaft.phase)*.025;shaft.g.rotation.x=-.12+Math.cos(t*.16+shaft.phase)*.013}
      turtle.position.set(-2.7+Math.sin(t*.12)*.55,4.9+Math.sin(t*.65)*.09,1+Math.sin(t*.12+.4)*.12);turtle.rotation.z=-.045+Math.sin(t*.53)*.023;turtle.rotation.y=-.43+Math.cos(t*.12)*.025;
      for(let i=0;i<flippers.length;i++){const f=flippers[i],stroke=Math.sin(t*1.05+(f.rear?1.1:0));f.pivot.rotation.x=f.side*(f.rear?.04:.10)+stroke*f.side*(f.rear?.10:.25);f.pivot.rotation.z=Math.cos(t*1.05+.5)*(f.rear?.04:.07)}
      for(let i=0;i<swimmers.length;i++){
        const f=swimmers[i];let dx,dy,dz;
        if(f.school){const u=t*.115;f.g.position.set(3.3+Math.sin(u)*2.6+f.offset.x,5.7+Math.sin(u*.9)*.25+f.offset.y,-3.7+Math.cos(u)*1.9+f.offset.z);dx=Math.cos(u)*2.6;dy=Math.cos(u*.9)*.225;dz=-Math.sin(u)*1.9}
        else{const u=t*f.speed+f.phase;f.g.position.set(f.base.x+Math.sin(u)*f.radius,f.base.y+Math.sin(u*.8+f.phase)*.16,f.base.z+Math.cos(u)*.75);dx=Math.cos(u)*f.radius;dy=Math.cos(u*.8+f.phase)*.128;dz=-Math.sin(u)*.75}
        f.g.rotation.y=Math.atan2(-dz,dx);f.g.rotation.z=Math.atan2(dy,Math.hypot(dx,dz));f.tail.rotation.y=Math.sin(t*5.8+f.phase)*.24;for(let j=0;j<f.pectorals.length;j++){const p=f.pectorals[j];p.pivot.rotation.y=Math.sin(t*4.2+f.phase)*p.s*.25}
      }
      for(let i=0;i<horses.length;i++){const h=horses[i];h.g.position.y=h.y+Math.sin(t*.64+h.phase)*.07;h.g.rotation.z=Math.sin(t*.44+h.phase)*.034;h.dorsal.rotation.y=Math.sin(t*19+h.phase)*.24}
      for(let i=0;i<grasses.length;i++){const blade=grasses[i];blade.g.rotation.z=Math.sin(t*1.1+blade.phase)*.14;blade.g.rotation.x=Math.sin(t*.83+blade.phase)*.075}
      for(let i=0;i<octopusArms.length;i++){const arm=octopusArms[i];arm.g.rotation.y=Math.sin(t*.65+arm.phase)*.043}
      for(let a=0;a<distant.length;a++){
        const animal=distant[a];animal.g.position.x=animal.base.x+Math.sin(t*.065+animal.phase)*3.3;animal.g.position.y=animal.base.y+Math.sin(t*.16+animal.phase)*.22;
        if(animal.kind==='ray'){
          if(updateHeavy){const attr=animal.wings.geometry.attributes.position,array=attr.array,base=animal.positions,phase=animal.wingPhase,amp=animal.wingAmplitude,offset=t*.85+animal.phase;for(let i=0;i<phase.length;i++)array[i*3+1]=base[i*3+1]+Math.sin(offset-phase[i])*amp[i];attr.needsUpdate=true}
        }else animal.tail.rotation.y=Math.sin(t*1.4)*.19;
      }
      for(let i=0;i<bubbles.length;i++){const b=bubbles[i];b.g.position.y=(b.y+t*b.speed)%14;b.g.position.x=b.x+Math.sin(t*.53+b.phase)*.13}
    }
    updateDynamicBatches();
  }
  // Split rendering from simulation. Camera/journey/rendering runs at native rAF
  // on desktop so 120/144 Hz scrolling can actually present at native refresh.
  // Marine-life transforms/uploads are capped at 60 FPS and mesh deformation at
  // 30 FPS, preventing high-refresh displays from doubling all CPU-side work.
  const targetRenderFPS=mobileRenderCap?60:0; // 0 = native requestAnimationFrame refresh rate
  const renderInterval=targetRenderFPS?1000/targetRenderFPS:0;
  const simulationInterval=1000/60;
  const heavyUpdateInterval=1000/30;
  let lastRendered=0,lastSimulation=0,lastHeavyMotion=0,scrollUntil=0,nextRenderDeadline=0;
  let fpsWindowStart=performance.now(),fpsWindowFrames=0,measuredRenderFPS=0;
  window.addEventListener('scroll',()=>{scrollUntil=performance.now()+220;renderInvalidated=true;queueAnimation()},{passive:true});
  function animate(now){
    if(!running||contextLost||document.hidden||!stageVisible){last=now;lastSimulation=now;return}
    const scrolling=now<scrollUntil,themeMoving=Math.abs(skyUniforms.uNight.value-night)>.001,continuous=!paused||scrolling||themeMoving;
    if(paused&&!continuous&&!renderInvalidated){last=now;nextRenderDeadline=0;return}

    // Only mobile uses an explicit 60 FPS render deadline. Desktop renders once
    // per display rAF. Scroll/camera state is therefore sampled every native frame.
    if(renderInterval){
      if(!nextRenderDeadline)nextRenderDeadline=now;
      if(now+.35<nextRenderDeadline){if(continuous)queueAnimation();return}
      nextRenderDeadline+=renderInterval;
      if(now-nextRenderDeadline>renderInterval*1.5)nextRenderDeadline=now+renderInterval;
    }else nextRenderDeadline=0;

    lastRendered=now;
    const dt=Math.min((now-last)/1000,.1);last=now;
    if(!paused){elapsed+=dt;time.value=elapsed}

    // Critical path for scroll feel: always update the camera/environment from the
    // latest scrollY immediately before this frame is rendered.
    updateJourney(dt);

    if(!paused){
      const simulationDue=!lastSimulation||now-lastSimulation>=simulationInterval-1;
      if(simulationDue){
        const heavy=now-lastHeavyMotion>=heavyUpdateInterval-1;
        update(elapsed,heavy);
        lastSimulation=now;
        if(heavy)lastHeavyMotion=now;
      }
    }

    renderJourney();renderInvalidated=false;
    fpsWindowFrames++;
    const fpsElapsed=now-fpsWindowStart;
    if(fpsElapsed>=600){measuredRenderFPS=Math.round(fpsWindowFrames*1000/fpsElapsed);fpsWindowFrames=0;fpsWindowStart=now}
    if(!paused||now<scrollUntil||Math.abs(skyUniforms.uNight.value-night)>.001)queueAnimation();
  }
  // First frame includes the exact same composed paths as all subsequent frames.
  update(0,true);finalizeDynamicBatchBounds();await renderer.compileAsync(scene,camera);await renderer.compileAsync(blackoutScene,camera);await renderer.compileAsync(anglerScene,camera);updateJourney(1);update(0,true);renderJourney();
  status.classList.add('hidden');document.body.dataset.ready='true';document.body.dataset.drawCalls=String(renderer.info.render.calls);document.body.dataset.triangles=String(renderer.info.render.triangles);
  // Read-only diagnostics for checking the delivered scene.
  window.reefDiagnostics=()=>({ready:true,paused,time:elapsed,quality:'full-universal',renderFPS:targetRenderFPS||'native',measuredRenderFPS,displayRefreshHz,highRefreshDisplay,mobileRenderCap,simulationFPS:60,heavyUpdateFPS:30,renderScale,renderScaleStrategy:'stable-pixel-budget-high-refresh-aware',maxRenderPixels:MAX_RENDER_PIXELS,minRenderScale,maxRenderScale,preBatchDrawCalls,postBatchDrawCalls,drawCallReduction:preBatchDrawCalls-postBatchDrawCalls,staticInstanceBatches:staticBatches.length,dynamicInstanceBatches:dynamicBatches.length,dynamicBatchCulling:true,batchedSources,detachedSources,mergedMeshSources,mergedGeometryBatches,frozenTransforms,dynamicBatchUploads,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,geometries:renderer.info.memory.geometries,textures:renderer.info.memory.textures,three:THREE.REVISION});
  last=performance.now();lastRendered=lastSimulation=nextRenderDeadline=0;fpsWindowStart=last;fpsWindowFrames=0;if(!paused)queueAnimation();
  window.addEventListener('pagehide',e=>{if(!e.persisted){running=false;cancelAnimationFrame(animationFrame);sceneObserver.disconnect();journeyObserver.disconnect();oceanObserver.disconnect();const geometries=new Set(),materials=new Set(),textures=new Set();for(const root of [scene,anglerScene,blackoutScene])root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);for(const m of (Array.isArray(o.material)?o.material:[o.material]))if(m){materials.add(m);for(const value of Object.values(m))if(value?.isTexture)textures.add(value);for(const u of Object.values(m.uniforms||{}))if(u.value?.isTexture)textures.add(u.value)}});for(const x of textures)x.dispose();for(const x of materials)x.dispose();for(const x of geometries)x.dispose();renderer.dispose()}});
}catch(error){showError(error)}

</script></body></html>